"""Parse mutmut mutation testing output."""

import platform
import re
import subprocess
import sys
from pathlib import Path


def _try_read_summary_json() -> dict | None:
    """Read mutation_summary.json if it exists (generated by
    generate_mutmut_report.py)."""
    for candidate in (Path("reports/mutmut/mutation_summary.json"),):
        if candidate.exists():
            import json

            try:
                data = json.loads(candidate.read_text(encoding="utf-8"))
                stats = data.get("stats", {})
                if stats.get("total", 0) > 0:
                    return {
                        "total_mutants": stats.get("total", 0),
                        "killed": stats.get("killed", 0),
                        "survived": stats.get("survived", 0),
                        "timeout": stats.get("timeout", 0),
                        "skipped": stats.get("skipped", 0),
                        "suspicious": stats.get("suspicious", 0),
                        "mutation_score": stats.get("mutation_score", 0),
                        "survived_files": data.get("survived_files", []),
                        "source": str(candidate),
                    }
            except (json.JSONDecodeError, KeyError):
                pass
    return None


def _try_read_results_txt() -> dict | None:
    """Read results.txt if it exists (generated by
    generate_mutmut_report.py)."""
    for candidate in (Path("reports/mutmut/results.txt"),):
        if candidate.exists():
            try:
                output = candidate.read_text(encoding="utf-8")
            except OSError:
                continue
            survived = 0
            killed = 0
            timeout_count = 0
            skipped = 0
            suspicious = 0
            for line in output.splitlines():
                line_lower = line.lower()
                # Emoji-based (mutmut 3.x)
                if "🎉" in line or re.search(r"killed\s+mutants?", line_lower):
                    m = re.search(r"(\d+)", line)
                    if m:
                        killed = int(m.group(1))
                elif "🙁" in line or "survived" in line_lower:
                    m = re.search(r"(\d+)", line)
                    if m:
                        survived = int(m.group(1))
                elif "⏰" in line or "timeout" in line_lower:
                    m = re.search(r"(\d+)", line)
                    if m:
                        timeout_count = int(m.group(1))
                elif "🤔" in line or "suspicious" in line_lower:
                    m = re.search(r"(\d+)", line)
                    if m:
                        suspicious = int(m.group(1))
                elif "⏭" in line or "skipped" in line_lower:
                    m = re.search(r"(\d+)", line)
                    if m:
                        skipped = int(m.group(1))
            total = survived + killed + timeout_count + skipped + suspicious
            if total > 0:
                score = (killed / total * 100) if total > 0 else 0
                return {
                    "total_mutants": total,
                    "killed": killed,
                    "survived": survived,
                    "timeout": timeout_count,
                    "skipped": skipped,
                    "suspicious": suspicious,
                    "mutation_score": round(score, 2),
                    "source": str(candidate),
                }
    return None


def parse(timeout: int = 300) -> dict:
    """Run mutmut and return structured results.

    Note: mutmut is slow. This only runs if explicitly requested.
    Returns a neutral result (not an error) when mutmut has not been
    run yet, so it does not pollute the quality report.
    On Windows, mutmut is not supported natively (requires WSL).

    If ``mutation_summary.json`` or ``results.txt`` from a previous
    ``make mutation`` run exist, those are read instead of invoking
    mutmut directly — this allows the quality report to include
    mutation data on Windows without re-running mutmut.
    """
    # Try cached results first (from make mutation)
    cached = _try_read_summary_json()
    if cached:
        return cached
    cached = _try_read_results_txt()
    if cached:
        return cached

    # mutmut does not support Windows natively
    if platform.system() == "Windows":
        return {
            "error": (
                "mutmut is not supported on Windows natively."
                " Use WSL or 'make mutation' in Docker."
            ),
            "hint": "make mutation  (runs mutmut inside the soar_api Docker container)",
        }
    result = subprocess.run(
        [sys.executable, "-m", "mutmut", "results"],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        return {
            "error": "mutmut not initialized or no results. Run 'mutmut run' first.",
            "hint": "mutmut run  (configured in [tool.mutmut] in pyproject.toml)",
        }
    output = result.stdout
    survived = 0
    killed = 0
    timeout_count = 0
    skipped = 0
    for line in output.splitlines():
        if "survived" in line.lower():
            survived += 1
        elif "killed" in line.lower():
            killed += 1
        elif "timeout" in line.lower():
            timeout_count += 1
        elif "skipped" in line.lower():
            skipped += 1
    total = survived + killed + timeout_count + skipped
    score = (killed / total * 100) if total > 0 else 0
    return {
        "total_mutants": total,
        "killed": killed,
        "survived": survived,
        "timeout": timeout_count,
        "skipped": skipped,
        "mutation_score": round(score, 2),
    }
